{"code":"import random

def generate(rng):
    h = rng.randint(10, 40)
    w = rng.randint(10, 40)
    # alternating 3/2 rows and 2/1 rows, as in the example
    grid = []
    for r in range(h):
        if r % 2 == 0:
            grid.append([3 if c % 2 == 0 else 2 for c in range(w)])
        else:
            grid.append([2 if c % 2 == 0 else 1 for c in range(w)])
    # erase several axis-aligned rectangular regions, generally with varied sizes
    n = rng.randint(1, max(2, min(8, (h*w)//80 + 1)))
    for _ in range(n):
        rh = rng.randint(1, max(1, min(h//3, 8)))
        rw = rng.randint(1, max(1, min(w//3, 8)))
        r0 = rng.randint(0, h-rh)
        c0 = rng.randint(0, w-rw)
        for r in range(r0, r0+rh):
            for c in range(c0, c0+rw):
                grid[r][c] = 0
    return grid"}

